182	    /**
183	     * Try to find a free location that is adjacent to the
184	     * given location. If there is none, return null.
185	     * The returned location will be within the valid bounds
186	     * of the field.
187	     * 
188	     * @param location The location from which to generate an adjacency.
189	     * @param objectType type to avoid.
190	     * 
191	     * @return A valid location within the grid area.
192	     */
193	    public Location freeAdjacentLocation(Location location, Class<?> objectType)
194	    {
195	        // The available free ones.
196	        List<Location> free = getFreeAdjacentLocations(location, objectType);
197	        
198	        if(free.size() > 0) 
199	        {
200	            return free.get(0);
201	        }
202	        else
203	        {
204	            return null;
205	        }
206	    }
