256	     * Return the depth of the field.
257	     * 
258	     * @return The depth of the field.
259	     */
260	    public int getDepth()
261	    {
262	        return depth;
263	    }
264	    
265	    /**
266	     * Return the width of the field.
267	     * 
268	     * @return The width of the field.
269	     */
270	    public int getWidth()
271	    {
272	        return width;
273	    }
274	}

